#include "resident/domains/tasks/task_source_projection.hpp"
// 同一原Offer不能既选延期又选首片受领；别的Offer原延期不受影响。
#include "task_personal_acceptance_profile.hpp"
#include "resident/domains/tasks/personal_messages/task_personal_message_profile.hpp"
#include "resident/domains/tasks/personal_reports/task_personal_report_profile.hpp"
#include <set>
namespace hanmo::resident {
Outcome<bool> decode_task_personal_acceptance_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){try{using namespace boundary;const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find("task_personal_message_acceptances"):nullptr;if(!block)return {true,false,{}};if(const auto* takeover=dynamic->find("political_takeover"))if(const auto* version=takeover->find("task_execution_version");version&&integer(*version,"political_takeover/task_execution_version")!=1)fail("TaskPersonalAcceptanceStaticPaymentsUnsupported","political_takeover/task_execution_version");fields(*block,{"version","profile","policies"},{},"task_personal_message_acceptances");if(get_int(*block,"version","acceptances")!=1||get_string(*block,"profile","acceptances")!=task_personal_acceptance_profile)unsupported("UnsupportedTaskPersonalAcceptanceProfile","acceptances");if(std::find(caps.begin(),caps.end(),task_personal_acceptance_capability)==caps.end())fail("TaskPersonalAcceptanceCapabilityRequired",task_personal_acceptance_capability);auto delivery=decode_task_personal_message_profile(scenario,caps);if(!delivery.ok)return delivery;if(!delivery.value)fail("TaskPersonalAcceptanceOriginalSourcesRequired","task_personal_message_deliveries");const auto handoff=get_string(scenario,"task_message_handoff_profile","scenario");if(handoff=="known_personal_delivery_and_sender_report_v4"){auto report=decode_task_personal_report_profile(scenario,caps);if(!report.ok)return report;if(!report.value)fail("TaskPersonalAcceptanceOriginalSourcesRequired","task_personal_message_reports");}else if(handoff!="known_personal_delivery_and_report_v3")fail("TaskPersonalAcceptanceOriginalSourcesRequired","task_message_handoff_profile");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<Integer> task_personal_acceptance_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){std::map<StableId,StableId> versions;for(const auto& row:modules)if(!versions.emplace(row).second)return {false,{},common_failure("DuplicateNativeModuleIdentity",row.first).error};auto selected=versions.find(task_personal_acceptance_module);if(selected==versions.end())return {true,0,{}};if(selected->second!="1")return {false,{},common_failure("UnsupportedTaskPersonalAcceptanceVersion").error};if(versions.count("task_takeover_execution")&&versions["task_takeover_execution"]!="1")return {false,{},common_failure("TaskPersonalAcceptanceStaticPaymentsUnsupported").error};auto delivery=task_personal_message_selected_version(modules);if(!delivery.ok)return delivery;if(delivery.value!=1)return {false,{},common_failure("TaskPersonalAcceptanceOriginalSourcesRequired").error};if(versions["task_message_handoffs"]=="4"){auto report=task_personal_report_selected_version(modules);if(!report.ok)return report;if(report.value!=1)return {false,{},common_failure("TaskPersonalAcceptanceOriginalSourcesRequired").error};}return {true,1,{}};}
Status validate_task_personal_acceptance_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const TaskPersonalAcceptanceState* state){auto selected=task_personal_acceptance_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(selected.value)!=(state!=nullptr)||(state&&state->version!=1))return common_failure("TaskPersonalAcceptanceProfileMismatch");if(!state)for(const auto& row:c.state().facts.rows())if(row.second.domain==task_personal_acceptance_module||row.second.kind==task_personal_acceptance_started_kind||row.second.kind==task_personal_acceptance_completed_kind||row.second.kind==task_personal_acceptance_interrupted_kind)return common_failure("TaskPersonalAcceptanceProfileRequired",row.first);return common_success();}
Status validate_task_personal_acceptance_extension_pair(const TaskPersonalAcceptanceCatalog& catalog,const TaskExtensionCatalog* extensions){if(extensions)for(const auto& p:catalog.policies)for(const auto& e:extensions->policies)if(p.offer_id==e.offer_id)return common_failure("TaskPersonalAcceptanceExtensionUnsupported",p.offer_id);return common_success();}
Outcome<bool> emit_task_personal_acceptance_fact_payload_fields(ProjectionWriter& w,const TaskPersonalAcceptanceState* state,const FactRecord& h){const bool known=h.kind==task_personal_acceptance_started_kind||h.kind==task_personal_acceptance_completed_kind||h.kind==task_personal_acceptance_interrupted_kind;if(!known&&h.domain!=task_personal_acceptance_module)return {true,false,{}};if(!state||!known||h.domain!=task_personal_acceptance_module)return {false,{},common_failure("TaskPersonalAcceptanceFactMismatch",h.id).error};auto status=emit_task_personal_acceptance_fact_fields(w,*state,h.id);if(!status.ok)return {false,{},status.error};w.field("kind",h.kind);w.field("domain",h.domain);return {w.status().ok,w.status().ok,w.status().error};}
Status emit_task_personal_acceptance_fact_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskPersonalAcceptanceState* state){std::size_t emitted=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool known=h.kind==task_personal_acceptance_started_kind||h.kind==task_personal_acceptance_completed_kind||h.kind==task_personal_acceptance_interrupted_kind;if(!known&&h.domain!=task_personal_acceptance_module)continue;if(!state||!known||h.id!=row.first||h.domain!=task_personal_acceptance_module)return common_failure("TaskPersonalAcceptanceFactMismatch",row.first);auto checked=w.object(row.first,[&](auto&out){auto status=emit_task_personal_acceptance_fact_fields(out,*state,row.first);if(!status.ok)return status;out.field("kind",h.kind);out.field("domain",h.domain);return out.status();});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->starts.size()+state->endings.size())return common_failure("TaskPersonalAcceptanceFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> task_personal_acceptance_fact_payloads(const CommonStore& c,const TaskPersonalAcceptanceState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_personal_acceptance_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_task_personal_acceptance_json_payloads(const CommonStore& c,const TaskPersonalAcceptanceState* state,const BoundaryValue& v){try{using namespace boundary;auto expected=task_personal_acceptance_fact_payloads(c,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"acceptances/facts"))if(!compare_boundary(field(field(v,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("TaskPersonalAcceptanceFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
